{"file_path": "src/utils/helpers.ts", "initial_content": "export const generateId = (): string => {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
}

export const formatDate = (date: string): string => {
  if (!date) return ''
  const d = new Date(date)
  return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
}

export const getDateRange = (startDate: string, endDate: string, current: boolean): string => {
  const start = formatDate(startDate)
  const end = current ? 'Present' : formatDate(endDate)
  return `${start} - ${end}`
}

export const validateEmail = (email: string): boolean => {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  return re.test(email)
}

export const validatePhone = (phone: string): boolean => {
  const re = /^[\d\s\-\+\(\)]+$/
  return re.test(phone)
}

export const validateUrl = (url: string): boolean => {
  try {
    new URL(url)
    return true
  } catch {
    return false
  }
}
"}

{"file_path": "src/components/CVPreview.tsx", "initial_content": "import { useCV } from '../contexts/CVContext'
import ModernTemplate from './templates/ModernTemplate'
import ClassicTemplate from './templates/ClassicTemplate'
import CreativeTemplate from './templates/CreativeTemplate'

export default function CVPreview() {
  const { cvData } = useCV()

  const renderTemplate = () => {
    switch (cvData.selectedTemplate) {
      case 'modern':
        return <ModernTemplate data={cvData} />
      case 'classic':
        return <ClassicTemplate data={cvData} />
      case 'creative':
        return <CreativeTemplate data={cvData} />
      default:
        return <ModernTemplate data={cvData} />
    }
  }

  return (
    <div className="bg-gray-100 p-4 rounded-lg">
      <div className="bg-white rounded-lg overflow-hidden shadow-xl">
        {renderTemplate()}
      </div>
    </div>
  )
}
"}

